            pub fn compose(sources: &[$crate::__private::semio_framework_os_io::ComposeSource<'_>]) -> Result<$crate::__private::semio_framework_os_io::Composition<<Self as $crate::__private::semio_framework_plugin_abi::ArtifactComposer>::Snapshot>, $crate::__private::semio_framework_os_io::ComposeError> { <Self as $crate::__private::semio_framework_plugin_abi::ArtifactComposer>::compose(sources) }
        }
    };
    (@children_ty $snapshot:ty) => { $crate::__private::semio_framework_plugin_abi::NoChildren<$snapshot> };
    (@children_ty $snapshot:ty, $children:ty) => { $children };
}

/// 🪆️ Whether a subset owns snapshot/diff/mutation types or derives behavior from a base dialect.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SubsetKind {
    Owning,
    Derived,
}

/// 🪆️ Declares one subset's lifecycle facets, runtime registration, and inline conformance tests.
#[macro_export]
macro_rules! subset {
    (
        $vis:vis owning dialect $artifact:literal / $standard:literal / $subset:literal {
            spec $spec:ident {
                construction: $construction:ty,
                analysis: $analysis:ty,
                composition: $composition:ty,
            }
            builder: $builder:ident,
            analyzer: $analyzer:ident,
            composer: $composer:ident,
            $(io: [$($io_entry:expr),+ $(,)?],)?
            $(validator: $validator:ty,)?
            $(examples: [$($example:expr),+ $(,)?],)?
        }
    ) => {
        $crate::derive_artifact_facets! {
            $vis spec $spec {
                construction: $construction,
                analysis: $analysis,
                composition: $composition,
            }
            builder: $builder,
            analyzer: $analyzer,
            composer: $composer,
        }

        #[doc(hidden)]
        pub mod __subset_registration {
            use super::*;
            use std::sync::{Once, OnceLock};

            pub const SUBSET_DIALECT: $crate::__private::semio_framework_artifact_reference::Dialect = $crate::__private::semio_framework_artifact_reference::Dialect {
                artifact_kind: $artifact,
                standard: $crate::__private::semio_framework_artifact_reference::StandardId($standard),
                subset: $crate::__private::semio_framework_artifact_reference::SubsetId($subset),
            };
            pub const KIND: $crate::SubsetKind = $crate::SubsetKind::Owning;
            static REGISTERED: Once = Once::new();
            $(static VALIDATOR_ENTRY: OnceLock<$crate::__private::semio_framework_os_io::SubsetValidatorEntry> = OnceLock::new();)?

            $(fn validator_entry() -> &'static $crate::__private::semio_framework_os_io::SubsetValidatorEntry {
                VALIDATOR_ENTRY.get_or_init($crate::__private::semio_framework_os_io::subset_validator_entry_of::<$validator>)
            })?

            pub async fn register() {
                REGISTERED.call_once(|| {
                    let mut entries = vec![$crate::__private::semio_framework_plugin_abi::composer_entry_of::<$composer>()];
                    $(entries.extend([$($io_entry),+]);)?
                    $crate::__private::semio_framework_os_io::register_composer_entries(&entries).expect("subset registration is Once-guarded — a failure here means a dialect collision, a real programmer error");
                    $($crate::__private::semio_framework_os_io::register_subset_validator(validator_entry()).expect("subset registration is Once-guarded — a failure here means a dialect collision, a real programmer error");)?
                });
            }

            $(pub const EXAMPLES: &'static [$crate::__private::semio_framework_plugin_app_builder::ExampleSource] = &[$($example),+];)?

            $crate::__semio_subset_owning_conformance_tests!($composition);
        }

        $vis use __subset_registration::{register as register_subset, KIND, SUBSET_DIALECT};
    };

    (
        $vis:vis derived dialect $artifact:literal / $standard:literal / $subset:literal {
            validator: $validator:ty,
            $(io: [$($io_entry:expr),+ $(,)?],)?
            $(positive: [$($pos_example:expr),+ $(,)?],)?
            $(negative: [$($neg_example:expr),+ $(,)?],)?
        }
    ) => {
        #[doc(hidden)]
        pub mod __subset_registration {
            use super::*;
            use std::sync::{Once, OnceLock};

            pub const SUBSET_DIALECT: $crate::__private::semio_framework_artifact_reference::Dialect = $crate::__private::semio_framework_artifact_reference::Dialect {
                artifact_kind: $artifact,
                standard: $crate::__private::semio_framework_artifact_reference::StandardId($standard),
                subset: $crate::__private::semio_framework_artifact_reference::SubsetId($subset),
            };
            pub const KIND: $crate::SubsetKind = $crate::SubsetKind::Derived;
            static REGISTERED: Once = Once::new();
            static VALIDATOR_ENTRY: OnceLock<$crate::__private::semio_framework_os_io::SubsetValidatorEntry> = OnceLock::new();

            fn validator_entry() -> &'static $crate::__private::semio_framework_os_io::SubsetValidatorEntry {
                VALIDATOR_ENTRY.get_or_init($crate::__private::semio_framework_os_io::subset_validator_entry_of::<$validator>)
            }

            pub async fn register() {
                REGISTERED.call_once(|| {
                    $crate::__private::semio_framework_os_io::register_subset_validator(validator_entry()).expect("subset registration is Once-guarded — a failure here means a dialect collision, a real programmer error");
                    $( $crate::__private::semio_framework_os_io::register_composer_entries(&[$($io_entry),+]).expect("subset registration is Once-guarded — a failure here means a dialect collision, a real programmer error"); )?
                });
            }

            $(pub const POSITIVE_EXAMPLES: &'static [$crate::__private::semio_framework_plugin_app_builder::ExampleSource] = &[$($pos_example),+];)?
            $(pub const NEGATIVE_EXAMPLES: &'static [$crate::__private::semio_framework_plugin_app_builder::ExampleSource] = &[$($neg_example),+];)?

            $crate::__semio_subset_derived_conformance_tests!($validator);
        }

        $vis use __subset_registration::{register as register_subset, KIND, SUBSET_DIALECT};
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __semio_subset_owning_conformance_tests {
    ($composition:ty) => {
        #[cfg(test)]
        mod conformance {
            use super::*;

            #[$crate::__private::semio_framework_async_macros::async_test]
            async fn subset_macro_owning_dialect_matches_spec() {
                assert_eq!(SUBSET_DIALECT, <$composition as $crate::__private::semio_framework_plugin_abi::ArtifactComposition>::WRITES);
            }
        }
    };
}

#[doc(hidden)]
#[macro_export]
macro_rules! __semio_subset_derived_conformance_tests {
    ($validator:ty) => {
        #[cfg(test)]
        mod conformance {
            use super::*;

            #[$crate::__private::semio_framework_async_macros::async_test]
            async fn subset_macro_derived_dialect_is_non_any() {
                assert_ne!(SUBSET_DIALECT.subset, $crate::__private::semio_framework_artifact_reference::SubsetId::ANY);
            }

            #[$crate::__private::semio_framework_async_macros::async_test]
