                register().await;
                let registered = $crate::__private::semio_framework_os_kernel::io::list_registered_subset_validator_dialects().await.expect("registered subset observation");
                assert_eq!(registered.iter().filter(|dialect| **dialect == SUBSET_DIALECT).count(), 1);
                let payload = $crate::__private::semio_framework_os_io::IoPayload::Text(String::new());
                let _ = <$validator as $crate::__private::semio_framework_os_io::SubsetValidator>::validate(&payload).await;
